ruleContent:
@js:
let d={};try{d=JSON.parse(result)}catch(e){d={kind:'error',title:'页面解析失败',summary:String(e)}}
function esc(v){return String(v==null?'':v).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;')}
const RAW='https://raw.githubusercontent.com/huoguotiankong/source-core-8d7/main/';
const CDN='https://cdn.jsdelivr.net/gh/huoguotiankong/source-core-8d7@main/';
let title=d.title||'🌈 阅读书源仓库',summary=d.summary||'',kind=d.kind||'info',action='',badgeHtml='',sectionHtml='';
let badges=Array.isArray(d.badges)?d.badges:[],sections=Array.isArray(d.sections)?d.sections:[];
for(let i=0;i<badges.length;i++)badgeHtml+='<i>'+esc(badges[i])+'</i>';
for(let i=0;i<sections.length;i++){let x=sections[i]||{};sectionHtml+='<div class="card"><b>'+esc(x.title||'说明')+'</b><p>'+esc(x.text||'').replace(/\\n/g,'<br>')+'</p></div>'}
function button(text,url,alt){return '<a class="btn'+(alt?' alt':'')+'" href="'+esc(url)+'">'+esc(text)+'</a>'}
if(kind==='rss'&&d.rssUrl){action=button('重新导入 / 更新仓库订阅源','legado://import/importonline?src='+d.rssUrl,false)}
if(kind==='bundle'&&d.bundlePath){let u=RAW+d.bundlePath,b=CDN+d.bundlePath;action=button('主线路批量导入','legado://import/importonline?src='+u,false)+button('备用线路批量导入','legado://import/importonline?src='+b,true)}
if(kind==='source'&&d.sourceUrl){let u=d.sourceUrl,b=d.backupUrl||'';action=button('从 GitHub 导入 / 更新书源','legado://import/importonline?src='+u,false);if(b)action+=button('备用线路导入','legado://import/importonline?src='+b,true)}
let html=`<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><style>:root{color-scheme:light dark;--bg:#f6f7fb;--card:#fff;--text:#202532;--muted:#727b8d;--line:#e6e9f0;--p1:#5d6dff;--p2:#9a5cff}@media(prefers-color-scheme:dark){:root{--bg:#10131a;--card:#191e27;--text:#eef2f8;--muted:#9ba5b7;--line:#2b3240;--p1:#7180ff;--p2:#a46cff}}*{box-sizing:border-box}body{margin:0;padding:18px;background:var(--bg);color:var(--text);font-family:-apple-system,BlinkMacSystemFont,"Segoe UI","PingFang SC","Microsoft YaHei",sans-serif}.wrap{max-width:720px;margin:auto}.hero{padding:22px;border-radius:22px;color:#fff;background:linear-gradient(135deg,var(--p1),var(--p2))}h1{font-size:23px;margin:0 0 9px}.hero p{line-height:1.65;margin:0;opacity:.94}.badges{display:flex;gap:7px;flex-wrap:wrap;margin-top:14px}.badges i{font-style:normal;font-size:12px;padding:6px 9px;border-radius:999px;background:rgba(255,255,255,.18)}.card{margin-top:14px;padding:16px;border:1px solid var(--line);background:var(--card);border-radius:17px}.card p{color:var(--muted);line-height:1.7;margin-bottom:0}.btn{display:block;margin-top:14px;padding:14px 16px;text-align:center;text-decoration:none;color:#fff;font-weight:700;border-radius:14px;background:linear-gradient(135deg,var(--p1),var(--p2))}.btn.alt{background:var(--card);color:var(--p1);border:1px solid var(--p1)}.tip{margin-top:12px;color:var(--muted);font-size:12px;line-height:1.6}.foot{text-align:center;color:var(--muted);font-size:12px;padding:20px 0}</style></head><body><div class="wrap"><div class="hero"><h1>${esc(title)}</h1><p>${esc(summary)}</p><div class="badges">${badgeHtml}</div></div>${sectionHtml}${action}<div class="tip">点击导入按钮后会回到阅读的在线导入窗口；确认目标书源后完成导入或覆盖更新。</div><div class="foot">🌈 阅读书源仓库 · 0.2.6-beta7</div></div></body></html>`;
try{java.startBrowser('data:text/html;base64,'+java.base64Encode(html),title)}catch(e){java.longToast('打开仓库详情失败：'+String(e))}
'';
